from pathlib import Path
from collections import Counter,defaultdict
import json,os

root=Path('C:/Users/Joshu/dev/ai-os')
data=json.loads((root/'research/2026-10-24-design-completeness/skills.json').read_text(encoding='utf-8'))
rows=data['records']; relevant=[r for r in rows if r['classification'] in ('primary','supporting')]
report=root/'design/skill-routing-audit.md'
def link(path):return '<'+os.path.relpath(path,report.parent).replace('\\','/')+'>'
lines=['---','type: reference','subject: Full design skill routing and runtime coverage','created: 2026-10-24','updated: 2026-10-24','aliases: [Design skill audit]','tags: [design, skills, claude, codex, llm-wiki]','sources: []','---','','# Every design skill has a route','','Start at [the design hub](README.md). This register covers design-primary skills and direct visual, component, research, browser and motion support. Metadata was read across all nine existing Claude/Codex catalog, project, home and plugin roots. Generic API/module design, database schema design, billing contract design and unrelated operational workflows were examined but kept out of the design subset.','','## Verified coverage on 2026-10-24','',f'- {len(rows):,} SKILL.md path records examined, including duplicate runtime copies and plugin versions.',f'- {len(relevant):,} relevant path records: {sum(r["classification"]=="primary" for r in relevant)} primary and {sum(r["classification"]=="supporting" for r in relevant)} supporting.',f'- {len({r["name"] for r in relevant})} distinct directory names, which are not guaranteed to be distinct capabilities because vendor namespaces can reuse names.',f'- {sum(r["editable"] for r in relevant)} editable relevant copies now contain a hub link. All appended bytes preserve the original file prefix, metadata and custom instructions.',f'- {sum(not r["editable"] for r in relevant)} plugin, bundled system or managed synced copies are read-only in this audit. Their companion routes appear below. Shared root/home instructions supply the incoming hub route without altering vendor packages.','- No missing editable design routes after live readback. No new global activation or replacement skill copies were created.','- Coverage excludes frozen `_snapshots`, dependency trees and Git internals. These are archives or implementation dependencies, not active or canonical skill entry points.','- This audit establishes routing and discoverability, not that every skill was executed, every tool authenticated, or every plugin present in both runtimes.','','The [machine-readable full inventory](../research/2026-10-24-design-completeness/skills.json) records every considered path, metadata, classification reason, editability, routing result and verification hash, including the general skills excluded from the design subset.','','| Root | Primary | Supporting | General |','|---|---:|---:|---:|']
for record in data['roots']:
    counts=Counter(r['classification'] for r in rows if r['root']==record['kind'])
    lines.append(f'| `{record["kind"]}` | {counts["primary"]} | {counts["supporting"]} | {counts["general"]} |')
lines+=['','','## Design and directly supporting capabilities','','Each row links a real installed/catalogued copy. Use its owning runtime path; a catalogue copy does not activate a skill. Namespace-specific and all duplicate paths remain in the full JSON register.','','| Skill directory name | Classification | Existing homes |','|---|---|---|']
groups=defaultdict(list)
for row in relevant:groups[row['name']].append(row)
for name,items in sorted(groups.items()):
    first=sorted(items,key=lambda x:(not x['root'].startswith('project'),not x['root'].startswith('catalog'),x['path']))[0]
    lines.append(f'| [{name}]({link(first["path"])}) | {", ".join(sorted({x["classification"] for x in items}))} | {", ".join(sorted({x["root"] for x in items}))} |')
lines+=['','','## Read-only companion registry','','These exact entry points connect vendor and managed skills to this hub without editing their installed packages. A package update may replace vendor instructions; refresh this audit when new skills are installed.','','| Installed entry point | Class | Reason kept read-only |','|---|---|---|']
for row in sorted((r for r in relevant if not r['editable']),key=lambda r:r['path']):
    reason='Plugin package' if row['root'].startswith('plugin') else ('Managed synced copy' if '/synced/' in row['path'] else 'Bundled system skill or symlink')
    lines.append(f'| [{row["path"]}]({link(row["path"])}) | {row["classification"]} | {reason} |')
lines+=['','','## How to keep this accurate','','When adding or changing a design skill, route its canonical and already-existing activated custom copies back to [README.md](README.md), without replacing customizations. Register vendor-owned skills here instead of editing package caches. Use the inventory runner to inspect newly discovered metadata, then review classifications before applying pointers. The inventory is a dated audit, not a background watcher.','','The sole compare-and-swap skip was a shared `orca-cli` copy whose other path had already received the block; a fresh read verified that it also contained the hub pointer. All other eligible edits were appended after their expected hash matched.','']
report.write_text('\n'.join(lines),encoding='utf-8')
print(f'Wrote {report}: {len(lines)} lines')
